import { TriangleAlertIcon } from "lucide-react";
import type { FC } from "react";
import { StatusIndicator } from "#/components/StatusIndicator/StatusIndicator";
import {
	Tooltip,
	TooltipContent,
	TooltipTrigger,
} from "#/components/Tooltip/Tooltip";

type ProvisionerVersionProps = {
	buildVersion: string | undefined;
	provisionerVersion: string;
};

export const ProvisionerVersion: FC<ProvisionerVersionProps> = ({
	provisionerVersion,
	buildVersion,
}) => {
	return provisionerVersion === buildVersion ? (
		<span className="text-xs font-medium text-content-secondary">
			Up to date
		</span>
	) : (
		<Tooltip>
			<TooltipTrigger asChild>
				<StatusIndicator
					variant="warning"
					size="sm"
					className="cursor-pointer"
					tabIndex={0}
				>
					<TriangleAlertIcon className="size-icon-xs" />
					Outdated
				</StatusIndicator>
			</TooltipTrigger>
			<TooltipContent className="max-w-xs">
				<p className="m-0">
					This provisioner is out of date. You may experience issues when using
					a provisioner version that doesn't match your Optimus IDE Collab deployment. Please
					upgrade to a newer version.
				</p>
			</TooltipContent>
		</Tooltip>
	);
};
